import { mountLearning } from './learning.js?v=learn2';
import { predictID3, predictGaussian, predictDocument, predictHeart, predictKNN, multiplyMatrix } from './engines.js';

const $ = selector => document.querySelector(selector);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titleCase = str => String(str).replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
const pct = value => (value * 100).toFixed(2) + '%';
const fmt = value => value == null ? '?' : typeof value === 'boolean' ? (value ? 'True' : 'False') : typeof value === 'number' ? Number(value.toFixed(4)).toString() : String(value);
const paths = {
  book:'M8 3C6 1 2 2 1 3v11c2-1 5-1 7 1 2-2 5-2 7-1V3c-1-1-5-2-7 0Zm0 0v12',
  code:'m6 5-4 3 4 3m4-6 4 3-4 3M9 2 7 14',
  output:'M2 3h12v10H2zM4.5 6l2 2-2 2m4 0h3',
  play:'m5 3 8 5-8 5z', database:'M14 4c0 1.1-2.7 2-6 2S2 5.1 2 4s2.7-2 6-2 6 .9 6 2ZM2 4v8c0 1.1 2.7 2 6 2s6-.9 6-2V4M2 8c0 1.1 2.7 2 6 2s6-.9 6-2',
  download:'M8 2v8m-3-3 3 3 3-3M2 11v3h12v-3', file:'M9 1H3v14h10V5ZM9 1v4h4M5 8h6M5 11h4',
  share:'M6 4H2v10h10v-4M8 2h6v6M14 2 7 9',search:'M10.5 6a4.5 4.5 0 1 1-9 0 4.5 4.5 0 0 1 9 0ZM9.5 9.5 14 14',
  copy:'M5 5h9v9H5zM11 5V2H2v9h3',check:'m3 8 3 3 7-7',left:'m10 3-5 5 5 5',right:'m6 3 5 5-5 5',
  chart:'M2 2v12h12M5 11V8m4 3V5m4 6V2', layers:'m8 1-7 4 7 4 7-4-7-4ZM1 8l7 4 7-4M1 11l7 4 7-4',
  arrow:'M2 8h12M9 3l5 5-5 5',clock:'M14 8A6 6 0 1 1 2 8a6 6 0 0 1 12 0ZM8 4v4l3 2'
};
const icon = name => `<svg class="icon" viewBox="0 0 16 16" aria-hidden="true"><path d="${paths[name] || paths.file}"/></svg>`;
const colors = ['#3264c8','#b39a5e','#8b79af'];
const navNames = ['ID3 algorithm','Naive Bayes classifier','Document classifier','Heart Bayesian network','EM & K-Means','K-nearest neighbors','5-fold validation','Google Colab'];
let lab, state = {id:1,tab:'learn',gaussian:'iris',fold:1,dataset:'',page:0,query:'',knnFilter:'all',x:0,y:1,row:0};
let toastTimer;
function toast(message) { const node=$('#toast'); node.textContent=message; node.classList.add('show'); clearTimeout(toastTimer); toastTimer=setTimeout(()=>node.classList.remove('show'),3000); }
async function copy(text) { try { await navigator.clipboard.writeText(text); toast('Copied to clipboard'); } catch { toast('Clipboard unavailable. You can select and copy the text.'); } }
function downloadText(text, name, type='text/plain') { const blob=new Blob([text],{type}); const url=URL.createObjectURL(blob); const a=document.createElement('a'); a.href=url; a.download=name; a.click(); setTimeout(()=>URL.revokeObjectURL(url),1000); }
function card(title,body,sub='',badge='') { return `<section class="card"><div class="card-header"><div><h2>${title}</h2>${sub?`<p class="card-subtitle">${sub}</p>`:''}</div>${badge?`<span class="badge">${badge}</span>`:''}</div>${body}</section>`; }
function note(text,warning=false) { return `<div class="note-box${warning?' warning':''}">${text}</div>`; }
function confusion(matrix,labels) { const n=labels.length; return `<div class="matrix ${n===2?'two':''}"><div></div>${labels.map(c=>`<div class="matrix-label">${esc(c)}</div>`).join('')}${matrix.map((row,i)=>`<div class="matrix-label row-label">${esc(labels[i])}</div>${row.map((v,j)=>`<div class="matrix-cell${i!==j?' off':''}">${v}</div>`).join('')}`).join('')}</div><p class="matrix-axis">Rows: actual class · Columns: predicted class</p>`; }
function probabilities(labels,values) { return labels.map((label,i)=>`<div class="probability-row"><div class="probability-label"><span>${esc(label)}</span><span>${pct(values[i])}</span></div><div class="probability-track"><div class="probability-fill" style="width:${Math.max(0,Math.min(100,values[i]*100))}%"></div></div></div>`).join(''); }
function resultPanel(title,description,body='') { return `<div class="result-panel"><div class="result-eyebrow">PREDICTION</div><div class="prediction-value">${esc(title)}</div><div class="prediction-description">${description}</div>${body}</div>`; }
function numericField(name,label,value,min='',max='',step='any') { return `<label class="field"><span class="field-label">${esc(label)}</span><input type="number" name="${esc(name)}" value="${esc(value)}" step="${step}" ${min!==''?`min="${min}"`:''} ${max!==''?`max="${max}"`:''} required></label>`; }
function selectField(name,label,options,value) { return `<label class="field"><span class="field-label">${esc(label)}</span><select name="${esc(name)}">${options.map(option=>{const [v,l]=Array.isArray(option)?option:[option,titleCase(option)];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`; }
function dataTable(headers,rows,classes=[]) { return `<div class="table-scroll"><table><thead><tr>${headers.map(h=>`<th scope="col">${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>`<td class="${classes[i]||''}">${esc(fmt(v))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`; }
function readRoute() { const p=new URLSearchParams(location.hash.slice(1)); const n=Number(p.get('experiment'))||1; state.id=n>=1&&n<=8?n:1; const tab=p.get('tab'); state.tab=['learn','pyq','output','interactive','dataset','program'].includes(tab)?tab:'learn'; state.dataset=lab.experiments[state.id-1].datasets[0]; state.page=0;state.query=''; }
function route(id,tab=state.tab) { const hash=`experiment=${id}&tab=${tab}`; if(location.hash.slice(1)===hash){render();return;} location.hash=hash; }
function renderNav() { $('#experiment-nav').innerHTML=lab.experiments.map((exp,i)=>`<button class="nav-item" data-exp="${exp.id}" ${state.id===exp.id?'aria-current="page"':''}><span class="nav-number">${String(exp.id).padStart(2,'0')}</span><span class="nav-title">${esc(navNames[i])}</span><span class="nav-arrow">›</span></button>`).join(''); $('#mobile-experiment').innerHTML=lab.experiments.map(e=>`<option value="${e.id}" ${e.id===state.id?'selected':''}>${String(e.id).padStart(2,'0')} — ${esc(navNames[e.id-1])}</option>`).join(''); }
function render() {
 const exp=lab.experiments[state.id-1]; renderNav(); $('#workspace').classList.toggle('learning-mode',state.tab==='learn'); $('#workspace').classList.toggle('pyq-mode',state.tab==='pyq'); document.title=`${exp.title} · ML Lab Companion`;
 $('#workspace').innerHTML=`<div class="hero"><div><div class="eyebrow"><b>EXPERIMENT ${String(exp.id).padStart(2,'0')}</b><span class="dot"></span>${esc(exp.category)}</div><h1>${esc(exp.title)}</h1><p class="hero-description">${esc(exp.description)}</p><div class="metadata"><span>${icon('database')}${esc(exp.datasetLabel)}</span><span>${icon('layers')}${esc(exp.split)}</span></div></div><div class="hero-actions"><button class="button" data-tab="program">${icon('code')} View program</button><a class="button primary" href="assets/Computing_Lab1_Record.pdf" target="_blank" rel="noopener">${icon('file')} Lab record</a></div></div><div class="metrics">${exp.metrics.map((m,i)=>`<div class="metric"><div class="metric-label">${esc(m.label)}</div><div class="metric-value">${esc(m.value)}</div><div class="metric-note">${esc(m.note)}</div><span class="metric-corner">${i===0?'↗':'·'}</span></div>`).join('')}</div><div class="tabbar" role="tablist" aria-label="Experiment views">${[['learn','Learn step by step','book'],['pyq','Previous-year questions','book'],['output','Output','output'],['interactive','Try it yourself','play'],['dataset','Dataset','database'],['program','Python program','code']].map(([id,label,ic])=>`<button id="tab-${id}" class="tab" role="tab" aria-selected="${id===state.tab}" aria-controls="tab-panel" data-tab="${id}">${icon(ic)}${label}${id==='program'?`<span class="tab-count">.py</span>`:''}</button>`).join('')}<span class="tab-extra">PYTHON 3.12 · VERIFIED RUN</span></div><div id="tab-panel" role="tabpanel" aria-labelledby="tab-${state.tab}" tabindex="0"></div>`;
 renderPanel();
}
function renderPanel() {
 const exp=lab.experiments[state.id-1], panel=$('#tab-panel');
 if(state.tab==='learn') mountLearning(panel,lab,state.id,{dataTable,confusion,downloadText});
 if(state.tab==='pyq') mountPYQ(panel,lab,state.id,{dataTable,downloadText});
 if(state.tab==='output') {panel.innerHTML=`<div class="content-stack">${outputVisual(exp)}${consoleOutput(exp)}${outputNote(exp)}</div>`; bindVisuals();}
 if(state.tab==='program') panel.innerHTML=programPanel(exp);
 if(state.tab==='dataset') {panel.innerHTML=datasetPanel(exp); renderDatasetRows();}
 if(state.tab==='interactive') {panel.innerHTML=`<div class="content-stack">${interactivePanel(exp)}${note('Interactive predictions use fitted parameters from the verified Python runs. These panels calculate in your browser; use the downloadable Python program or Colab notebook to train the models again.')}</div>`; bindInteractive();}
}
function consoleOutput(exp) {return `<section class="card console-card"><div class="card-header"><div class="console-title"><span class="status-dot"></span><h2>Captured console output</h2><span class="badge muted">${exp.output.trim().split('\n').length} lines</span></div><div class="compact-actions"><button data-action="copy-output" title="Copy console output">${icon('copy')} Copy</button><button data-action="download-output" title="Download output text">${icon('download')} Save</button></div></div><pre class="console" tabindex="0" aria-label="Full recorded Python output">${esc(exp.output.trim())}</pre><div class="console-footer">${icon('check')} Successful local Python run · Exit code 0 · Scroll for the full output</div></section>`;}
function outputNote(exp) { if(exp.id===1) return note('The 14/14 result measures training fit. It does not estimate accuracy on unseen weather records. Use “Try it yourself” to follow a new sample through the tree.'); if(exp.id===4)return note('Educational inference on the UCI Cleveland dataset. The model and its probability estimates are not clinically validated.',true); if(exp.id===8)return note('This output was captured on a local Python runtime. Colab file upload, Google Drive authorization and downloads require an actual Colab session.'); return `<p class="section-note">Results use the included datasets and fixed splits. Open the Dataset tab for the complete data, or the Python program tab for the exact implementation.</p>`; }
function treeSvg(highlight=[]) {
 let leafCount=0,nodes=[],edges=[];
 function layout(node,depth,parent=null,branch='') {const item={node,depth,parent,branch,id:nodes.length,x:0,y:45+depth*115};nodes.push(item);if(node.attribute===null){item.x=80+leafCount++*175;}else{const children=Object.entries(node.children).map(([v,n])=>layout(n,depth+1,item,v));item.x=children.reduce((s,n)=>s+n.x,0)/children.length;}if(parent)edges.push(item);return item;}
 layout(lab.models.id3,0); const width=160+(leafCount-1)*175, height=Math.max(...nodes.map(n=>n.y))+48;
 return `<svg class="diagram-svg" viewBox="0 0 ${width} ${height}" role="img" aria-label="Learned weather decision tree with outlook, humidity and windy decision nodes">${edges.map(item=>{const active=highlight.some(p=>p.attribute===item.parent.node.attribute&&p.value===item.branch);const x=(item.x+item.parent.x)/2,y=(item.y+item.parent.y)/2;return `<path d="M${item.parent.x} ${item.parent.y+21} C${item.parent.x} ${y},${item.x} ${y},${item.x} ${item.y-21}" fill="none" stroke="${active?'#3264c8':'#ccd2da'}" stroke-width="${active?3:1.5}"/><rect x="${x-31}" y="${y-10}" width="62" height="20" rx="4" fill="#fff"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="${active?'#3264c8':'#828d9c'}" font-size="11">${esc(titleCase(item.branch))}</text>`;}).join('')}${nodes.map(item=>{const leaf=item.node.attribute===null,yes=item.node.prediction==='yes';return `<g><rect x="${item.x-59}" y="${item.y-21}" width="118" height="42" rx="7" fill="${leaf?(yes?'#e7ecf2':'#fbf3e3'):'#fff'}" stroke="${leaf?(yes?'#b8c4d4':'#e2d0ad'):'#a5aebb'}"/><text x="${item.x}" y="${item.y+5}" text-anchor="middle" font-size="13" font-weight="550" fill="${leaf?(yes?'#3264c8':'#9b783c'):'#39485e'}">${leaf?'Play: '+titleCase(item.node.prediction):titleCase(item.node.attribute)}</text></g>`;}).join('')}</svg>`;
}
function outputVisual(exp) {
 if(exp.id===1) return `<div class="split-grid">${card('Learned decision tree',`<div class="tree-area">${treeSvg()}<div class="tree-legend"><span><i class="legend-dot" style="background:#d8e0ea"></i>Yes</span><span><i class="legend-dot" style="background:#f0e3c8"></i>No</span><span>Follow one branch per feature</span></div></div>`,'ID3 · categorical splits', '14 RECORDS')}${card('Why outlook comes first',`<div class="card-body"><p class="insight">ID3 chooses the attribute with the <b>highest information gain</b> at each step.</p>${[['Outlook',.2467],['Humidity',.1518],['Windy',.0481],['Temperature',.0292]].map(([label,gain])=>`<div class="gain-row"><div class="gain-label"><span>${label}</span><span>${gain.toFixed(4)}</span></div><div class="gain-track"><div class="gain-fill" style="width:${gain/.2467*100}%"></div></div></div>`).join('')}<div style="margin-top:20px"><button class="button text" data-tab="interactive">Trace a new sample ${icon('arrow')}</button></div></div>`)}</div>`;
 if(exp.id===2) return `<div class="two-charts">${['iris','wine'].map(name=>card(titleCase(name)+' confusion matrix',`<div class="card-body">${confusion(lab.models.gaussian[name].matrix,lab.models.gaussian[name].classes)}</div>`,name==='iris'?'30 held-out records':'36 held-out records')).join('')}</div>`;
 if(exp.id===3) return `<div class="split-grid">${card('Ham vs spam',`<div class="card-body">${confusion([[900,4],[12,116]],['ham','spam'])}</div>`,'Confusion matrix · 1,032 held-out documents')}${card('A vocabulary built on training data',`<div class="card-body"><ul class="info-list"><li><span class="info-number">01</span><span>Remove blank, conflicting and duplicate messages before splitting.</span></li><li><span class="info-number">02</span><span>Learn word counts from the 4,127 training documents only.</span></li><li><span class="info-number">03</span><span>Use Multinomial Naive Bayes with Laplace smoothing.</span></li></ul><div style="margin-top:18px"><button class="button text" data-tab="interactive">Classify a message ${icon('arrow')}</button></div></div>`)}</div>`;
 if(exp.id===4) return `<div class="split-grid">${card('Learned Bayesian network',`<figure class="image-figure"><img src="assets/heart_network.png" alt="Learned Bayesian network with target connected to chest pain, thal, vessels and maximum heart rate" loading="lazy"></figure>`,'Training data · discrete BIC structure learning','14 NODES')}${card('Held-out evaluation',`<div class="card-body">${confusion([[28,5],[3,25]],['absence','presence'])}<p class="insight" style="margin-top:20px">Training-only discretization and smoothed conditional probability tables preserve valid states for all features.</p><button class="button text" data-tab="interactive">Inspect an evidence profile ${icon('arrow')}</button></div>`,'61 records · target 0 / 1')}</div>`;
 if(exp.id===5) return clusteringView(false);
 if(exp.id===6) {const rows=lab.models.knn.predictions.filter(r=>!r.correct);return card('The three incorrect predictions',dataTable(['Row','Sepal L','Sepal W','Petal L','Petal W','Actual','Predicted'],rows.map(r=>[r.row+1,r['sepal length (cm)'],r['sepal width (cm)'],r['petal length (cm)'],r['petal width (cm)'],r.actual,r.predicted])),'k = 3 · standardized Euclidean distance','57 / 60 CORRECT');}
 if(exp.id===7) return card('Accuracy across the five folds',`<div class="card-body">${foldBars()}<p class="section-note" style="margin-top:18px">Each class contributes ten validation records per fold. The model is trained again inside each fold.</p><button class="button text" data-tab="interactive">Inspect fold metrics ${icon('arrow')}</button></div>`,'Stratified · shuffled with random_state = 42');
 return `<div class="split-grid">${card('A small data workflow',`<figure class="image-figure"><img src="assets/colab_demo.png" alt="Bar chart of student A with 78 marks, B with 85 and C with 92" loading="lazy"></figure>`,'Create a DataFrame → save CSV → plot')}${card('Explore in Google Colab',`<div class="card-body"><ol class="step-list"><li>Upload the provided notebook.</li><li>Connect to a Python runtime.</li><li>Run setup and data cells.</li><li>Run each experiment separately.</li><li>Save or download your results.</li></ol><a class="button" href="assets/Computing_Lab1.ipynb" download style="margin-top:18px">${icon('download')} Get notebook</a></div>`,'No GPU is required')}</div>`;
}
function foldBars() {return `<div class="fold-bar-chart">${lab.models.cv.folds.map(f=>`<div class="fold-bar-column ${state.fold===f.fold?'active':''}"><span>${pct(f.accuracy)}</span><div class="fold-bar" style="height:${f.accuracy*140}px"></div></div>`).join('')}</div><div class="fold-bar-labels">${lab.models.cv.folds.map(f=>`<span>FOLD ${f.fold}</span>`).join('')}</div>`;}
function highlightSource(source) {
 const tokens=/("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*'|#[^\n]*|\b(?:from|import|as|class|def|return|if|else|elif|for|in|while|not|and|or|is|None|True|False|raise|try|except|with|lambda|assert)\b|\b\d+(?:\.\d+)?\b)/g;
 let docstring=false;
 return source.split('\n').map((line,i)=>{const stripped=line.trim();if(stripped.startsWith('"""')){const oneLine=stripped.length>3&&stripped.endsWith('"""');if(!oneLine)docstring=!docstring;return `<span class="code-line"><span class="line-number">${i+1}</span><span class="code-comment">${esc(line)}</span></span>`;}if(docstring)return `<span class="code-line"><span class="line-number">${i+1}</span><span class="code-comment">${esc(line)}</span></span>`;let last=0,output='';for(const match of line.matchAll(tokens)){output+=esc(line.slice(last,match.index));const value=match[0];const cls=value.startsWith('#')?'comment':value.startsWith('"')||value.startsWith("'")?'string':/^\d/.test(value)?'number':'keyword';output+=`<span class="code-${cls}">${esc(value)}</span>`;last=match.index+value.length;}output+=esc(line.slice(last));return `<span class="code-line"><span class="line-number">${i+1}</span><span>${output||' '}</span></span>`;}).join('');
}
function programPanel(exp) {return `<div class="content-stack">${note('This is the complete Python program used for the captured output. Download the program package for its datasets and requirements, or open the Colab notebook to execute it.')}<section class="card"><div class="program-toolbar"><div class="program-filename">${icon('code')}${esc(exp.filename)} <span class="badge muted">${exp.source.trim().split('\n').length} lines</span></div><div class="compact-actions"><button data-action="copy-source">${icon('copy')} Copy code</button><a class="button" href="assets/${exp.filename}" download>${icon('download')} Download .py</a></div></div><pre class="program-view" tabindex="0" aria-label="Full Python source code"><code>${highlightSource(exp.source)}</code></pre></section><a class="link-arrow" href="assets/Computing_Lab1_Programs.zip" download>Download every program with datasets and requirements ${icon('arrow')}</a></div>`;}
function datasetPanel(exp) {return `<div class="content-stack">${note(exp.id===4?'Original UCI Cleveland coding is retained. Target 0 = absence; target 1 = presence. “?” denotes a missing value. Continuous features are binned from training data only.':exp.id===3?'The complete original SMS dataset is shown here. Cleaning and deduplication produce the 5,159 unique documents used by the classifier.':'Complete dataset, with the original values used by the Python programs. Row numbers below are one-based CSV record numbers.')}<section class="card"><div class="dataset-toolbar"><div class="control-row"><select id="dataset-select" class="styled-input" aria-label="Choose dataset">${exp.datasets.map(name=>`<option value="${name}" ${name===state.dataset?'selected':''}>${titleCase(name)} · ${lab.datasets[name].count.toLocaleString()} rows</option>`).join('')}</select><a id="dataset-download" class="button" href="assets/${state.dataset}.csv" download>${icon('download')} Download CSV</a></div><div class="search-wrap">${icon('search')}<input id="dataset-search" class="search-input" placeholder="Search all records…" aria-label="Search all dataset records" value="${esc(state.query)}"></div></div><div id="dataset-rows"></div><div class="pagination"><span id="dataset-range"></span><div class="pagination-actions"><button class="icon-button" data-action="page-prev" aria-label="Previous dataset page">${icon('left')}</button><button class="icon-button" data-action="page-next" aria-label="Next dataset page">${icon('right')}</button></div></div></section></div>`;}
function renderDatasetRows() {const data=lab.datasets[state.dataset],query=state.query.toLowerCase();const filtered=data.rows.map((row,index)=>({row,index})).filter(({row})=>!query||row.some(x=>String(x??'?').toLowerCase().includes(query)));const pages=Math.max(1,Math.ceil(filtered.length/12));state.page=Math.max(0,Math.min(state.page,pages-1));const chunk=filtered.slice(state.page*12,state.page*12+12);const classes=state.dataset==='spam'?['','','message-cell']:[];$('#dataset-rows').innerHTML=chunk.length?dataTable(['Row',...data.columns],chunk.map(({row,index})=>[index+1,...row]),classes):'<div class="empty-state">No records match this search.</div>';$('#dataset-range').textContent=filtered.length?`${state.page*12+1}–${Math.min(state.page*12+12,filtered.length)} of ${filtered.length.toLocaleString()} records${query?' matched':''}`:'0 records';$('[data-action="page-prev"]').disabled=state.page===0;$('[data-action="page-next"]').disabled=state.page>=pages-1;}
function interactivePanel(exp) {
 if(exp.id===1)return `<div class="split-grid">${card('Choose weather conditions',`<div class="card-body"><form id="id3-form"><div class="form-grid">${selectField('outlook','Outlook',['sunny','overcast','rainy','unseen'],'sunny')}${selectField('temperature','Temperature',['hot','mild','cool'],'hot')}${selectField('humidity','Humidity',['high','normal'],'normal')}${selectField('windy','Windy',[['False','No'],['True','Yes']],'False')}</div><div class="form-actions"><button class="button primary" type="submit">${icon('play')} Classify sample</button><span>Categorical ID3</span></div></form></div>`,'Follow the fitted tree for a new sample')}<div id="prediction-result" aria-live="polite"></div></div>${card('Decision path',`<div class="tree-area" id="try-tree"></div>`,'The selected branches are highlighted')}`;
 if(exp.id===2){const model=lab.models.gaussian[state.gaussian];return `<div class="split-grid">${card('Enter a numerical sample',`<div class="card-body"><div class="control-row" style="margin-bottom:18px"><label class="field-label" for="gaussian-dataset">Model</label><select id="gaussian-dataset" class="styled-input">${['iris','wine'].map(n=>`<option ${state.gaussian===n?'selected':''} value="${n}">${titleCase(n)}</option>`).join('')}</select></div><form id="gaussian-form"><div class="form-grid ${state.gaussian==='wine'?'wide':''}">${model.features.map((name,i)=>numericField('f'+i,titleCase(name),model.defaults[i],0)).join('')}</div><div class="form-actions"><button class="button primary" type="submit">${icon('play')} Predict class</button></div></form></div>`,'Use the parameters learned on the training split')}<div id="prediction-result" aria-live="polite"></div></div>`;}
 if(exp.id===3)return `<div class="split-grid">${card('Classify a new document',`<div class="card-body"><form id="document-form"><label class="field-label" for="message-input">SMS message</label><textarea id="message-input" name="message" required maxlength="10000">Congratulations! Claim your free cash prize now</textarea><div class="sample-buttons"><button type="button" class="sample-button" data-sample="spam">Prize offer</button><button type="button" class="sample-button" data-sample="ham">Classroom message</button></div><div class="form-actions"><button class="button primary" type="submit">${icon('play')} Classify message</button></div></form></div>`,'Word counts · training-only vocabulary')}<div id="prediction-result" aria-live="polite"></div></div>`;
 if(exp.id===4){const model=lab.models.heart,labels={age:'Age (years)',trestbps:'Resting blood pressure',chol:'Cholesterol',thalach:'Maximum heart rate',oldpeak:'ST depression',sex:'Sex',cp:'Chest pain type',fbs:'Fasting blood sugar > 120',restecg:'Resting ECG',exang:'Exercise-induced angina',slope:'ST slope',ca:'Major vessels',thal:'Thal state'};const opts={sex:[[0,'0 · Female'],[1,'1 · Male']],cp:[[1,'1 · Typical angina'],[2,'2 · Atypical angina'],[3,'3 · Non-anginal'],[4,'4 · Asymptomatic']],fbs:[[0,'0 · No'],[1,'1 · Yes']],exang:[[0,'0 · No'],[1,'1 · Yes']],thal:[[3,'3 · Normal'],[6,'6 · Fixed defect'],[7,'7 · Reversible defect']]};return `${note('Educational dataset exploration only. These target predictions and probabilities are not clinically validated.',true)}<div class="split-grid">${card('Evidence profile',`<div class="card-body"><form id="heart-form"><div class="form-grid">${model.features.map(name=>model.continuous.includes(name)?numericField(name,labels[name],model.defaultRaw[name],0):selectField(name,labels[name],opts[name]||model.states[name].map(x=>[x,String(x)]),model.defaultRaw[name])).join('')}</div><div class="form-actions"><button class="button primary" type="submit">${icon('play')} Infer dataset target</button></div></form></div>`,'Initial values are from the first held-out record')}<div id="prediction-result" aria-live="polite"></div></div>`;}
 if(exp.id===5)return clusteringView(true);
 if(exp.id===6){const model=lab.models.knn;return `<div class="split-grid">${card('Find the nearest training records',`<div class="card-body"><form id="knn-form"><div class="form-grid">${lab.datasets.iris.columns.slice(0,4).map((name,i)=>numericField('f'+i,titleCase(name),model.default[i],0)).join('')}${selectField('k','Number of neighbors',Array.from({length:15},(_,i)=>[i+1,'k = '+(i+1)]),3)}</div><div class="form-actions"><button class="button primary" type="submit">${icon('play')} Find neighbors</button><span>Training-fitted scaling</span></div></form></div>`,'Distance is computed using standardized measurements')}<div id="prediction-result" aria-live="polite"></div></div>${card('Nearest neighbors',`<div id="neighbors-table"></div>`,'Closest training records, ordered by distance')}`;}
 if(exp.id===7)return card('Inspect a validation fold',`<div class="card-body"><div class="fold-buttons">${lab.models.cv.folds.map(f=>`<button class="fold-button${state.fold===f.fold?' active':''}" data-fold="${f.fold}">Fold ${f.fold}</button>`).join('')}</div><div id="fold-result"></div></div>`,'120 training records · 30 validation records per fold');
 return `<div class="summary-grid">${card('NumPy-style matrix multiplication',`<div class="card-body"><p class="insight">Edit A and calculate <b>A @ A</b>. The original Python program uses the same operation.</p><form id="matrix-form"><div class="matrix-equation"><div class="mini-matrix">${[1,2,3,4].map((n,i)=>`<input type="number" aria-label="Matrix row ${Math.floor(i/2)+1} column ${i%2+1}" name="m${i}" value="${n}" min="-100000" max="100000" required>`).join('')}</div><span class="matrix-symbol">→</span><div class="mini-matrix" id="matrix-result" aria-live="polite"></div></div><div class="form-actions"><button class="button primary" type="submit">Calculate A @ A</button></div></form></div>`,'Interactive numerical operations')}${card('A small pandas-style dataset',`<div class="card-body"><form id="marks-form"><div class="form-grid">${[78,85,92].map((n,i)=>numericField('mark'+i,'Student '+['A','B','C'][i],n,0,100,1)).join('')}</div><div class="form-actions"><button type="submit" class="button primary">Update summary</button><button type="button" class="button" data-action="download-marks">${icon('download')} CSV</button></div></form><div id="marks-result" style="margin-top:20px" aria-live="polite"></div></div>`,'Calculate the mean and export your CSV')}</div>${card('Run the original programs in Colab',`<div class="card-body"><ol class="step-list"><li>Download the notebook below and upload it to Google Colab.</li><li>Run the setup and embedded-dataset cells first.</li><li>Run each experiment separately with Shift+Enter.</li><li>Use the optional cells for upload, Drive authorization and result download.</li></ol><div class="form-actions"><a class="button primary" href="assets/Computing_Lab1.ipynb" download>${icon('download')} Download notebook</a><a class="button" href="https://colab.research.google.com/" target="_blank" rel="noopener">Open Google Colab ${icon('share')}</a></div></div>`,'Colab hardware and session availability vary')}`;
}
function bindInteractive() {
 const id=state.id;
 const runner=()=>{try{
  if(id===1){const sample=Object.fromEntries(new FormData($('#id3-form'))),r=predictID3(lab.models.id3,sample);$('#prediction-result').innerHTML=resultPanel('Play: '+titleCase(r.label),r.fallback?'This category is unseen. The tree uses the majority class at the current node.':'The sample follows these decision branches:',r.path.map(p=>`<div class="path-step">${esc(titleCase(p.attribute))} = ${esc(p.value)}</div>`).join(''));$('#try-tree').innerHTML=treeSvg(r.path);}
  if(id===2){const m=lab.models.gaussian[state.gaussian],form=new FormData($('#gaussian-form')),r=predictGaussian(m,m.features.map((_,i)=>Number(form.get('f'+i))));$('#prediction-result').innerHTML=resultPanel(titleCase(r.label),'Normalized model scores for the entered sample. These values are not calibrated confidence estimates.',probabilities(m.classes,r.probabilities));}
  if(id===3){const message=$('#message-input').value,r=predictDocument(lab.models.document,message);$('#prediction-result').innerHTML=resultPanel(titleCase(r.label),'The message is scored using the fitted training vocabulary.',probabilities(lab.models.document.classes,r.probabilities)+`<p class="prediction-description" style="margin-top:18px">${r.matchedWords.length} known words · ${r.unknown} unrecognized tokens</p><div class="sample-buttons">${r.matchedWords.slice(0,20).map(w=>`<span class="pill">${esc(w)}</span>`).join('')}</div>${r.matchedWords.length?'':'<p class="prediction-description">No words matched; only the learned class priors contribute.</p>'}`);}
  if(id===4){const raw=Object.fromEntries(new FormData($('#heart-form'))),r=predictHeart(lab.models.heart,raw);$('#prediction-result').innerHTML=resultPanel('Target '+r.label,r.label===0?'Dataset label: absence. This is an educational model output.':'Dataset label: presence. This is an educational model output.',probabilities(['Absence · 0','Presence · 1'],r.probabilities)+`<p class="prediction-description" style="margin-top:18px">Evidence after training-set discretization:</p>${Object.entries(r.evidence).map(([k,v])=>`<div class="path-step">${esc(k)} = ${v}</div>`).join('')}`);}
  if(id===6){const form=new FormData($('#knn-form')),r=predictKNN(lab.models.knn,[0,1,2,3].map(i=>Number(form.get('f'+i))),Number(form.get('k')));$('#prediction-result').innerHTML=resultPanel(titleCase(r.label),'The majority class among the nearest standardized training records.',probabilities(Object.keys(r.votes),Object.values(r.votes).map(n=>n/r.neighbors.length)));$('#neighbors-table').innerHTML=dataTable(['Training row','Species','Euclidean distance'],r.neighbors.map(n=>[n.row,n.label,n.distance]));}
  if(id===7)updateFold();
  if(id===8){const m=new FormData($('#matrix-form')),r=multiplyMatrix([0,1,2,3].map(i=>Number(m.get('m'+i))));$('#matrix-result').innerHTML=r.map(n=>`<div class="matrix-number">${fmt(n)}</div>`).join('');updateMarks();}
 }catch(error){const result=$('#prediction-result');if(result)result.innerHTML=`<div class="result-panel result-error">${esc(error.message)}</div>`;else toast(error.message);}};
 for(const form of $('#tab-panel').querySelectorAll('form'))form.addEventListener('submit',e=>{e.preventDefault();runner();});
 if(id===5)bindVisuals(); else runner();
}
function updateMarks(){const form=new FormData($('#marks-form')),values=[0,1,2].map(i=>Number(form.get('mark'+i))),mean=values.reduce((a,b)=>a+b)/3;$('#marks-result').innerHTML=`<div class="result-eyebrow">MEAN MARK</div><div class="prediction-value">${fmt(mean)}</div><div style="display:flex;gap:16px;height:110px;align-items:flex-end">${values.map((v,i)=>`<div style="flex:1;text-align:center;font-size:9px;color:#697689"><span>${v}</span><div style="background:#8195b1;height:${v*.7}px;border-radius:3px 3px 0 0;margin:4px auto;width:65%"></div><span>Student ${['A','B','C'][i]}</span></div>`).join('')}</div>`;}
function updateFold(){const f=lab.models.cv.folds[state.fold-1];$('#tab-panel').querySelectorAll('[data-fold]').forEach(b=>b.classList.toggle('active',Number(b.dataset.fold)===state.fold));$('#fold-result').innerHTML=`<div class="fold-metrics">${[['Accuracy',f.accuracy],['Precision',f.precision],['Recall',f.recall],['F1-score',f.f1]].map(([name,v])=>`<div class="fold-metric"><b>${pct(v)}</b><span>${name}${name!=='Accuracy'?' · macro':''}</span></div>`).join('')}</div><div class="split-grid"><div>${confusion(f.matrix,lab.models.cv.classes)}</div><div><p class="insight"><b>Validation records in fold ${f.fold}</b><br/>These records are excluded from model fitting in this fold.</p><p class="section-note">CSV rows: ${f.validationRows.map(x=>x+1).join(', ')}</p></div></div>`;}
function scatter(method) {
 const model=lab.models.clustering,points=model.scaled,labels=method==='kmeans'?model.kmeans:model.em;
 const W=480,H=330,margin={l:49,r:24,t:16,b:49};
 const xs=points.map(p=>p[state.x]),ys=points.map(p=>p[state.y]);const minX=Math.floor(Math.min(...xs)*2)/2-.3,maxX=Math.ceil(Math.max(...xs)*2)/2+.3,minY=Math.floor(Math.min(...ys)*2)/2-.3,maxY=Math.ceil(Math.max(...ys)*2)/2+.3;
 const x=v=>margin.l+(v-minX)/(maxX-minX)*(W-margin.l-margin.r),y=v=>H-margin.b-(v-minY)/(maxY-minY)*(H-margin.t-margin.b);
 let grid='';for(let i=0;i<5;i++){const vx=minX+(maxX-minX)*i/4,vy=minY+(maxY-minY)*i/4;grid+=`<line x1="${x(vx)}" y1="${margin.t}" x2="${x(vx)}" y2="${H-margin.b}" stroke="#e7ebf1"/><text x="${x(vx)}" y="${H-margin.b+20}" font-size="9" fill="#959fad" text-anchor="middle">${vx.toFixed(1)}</text><line x1="${margin.l}" y1="${y(vy)}" x2="${W-margin.r}" y2="${y(vy)}" stroke="#e7ebf1"/><text x="${margin.l-9}" y="${y(vy)+3}" text-anchor="end" font-size="9" fill="#959fad">${vy.toFixed(1)}</text>`;}
 const short=['Sepal length','Sepal width','Petal length','Petal width'];
 return `<svg viewBox="0 0 ${W} ${H}" class="diagram-svg" role="img" aria-label="${method==='kmeans'?'K-Means':'EM'} clusters on standardized ${short[state.x]} and ${short[state.y]}">${grid}${points.map((p,i)=>`<circle cx="${x(p[state.x])}" cy="${y(p[state.y])}" r="${i===state.row?6:3.8}" fill="${colors[labels[i]]}" fill-opacity="${i===state.row?1:.7}" stroke="${i===state.row?'#14253d':'#fff'}" stroke-width="${i===state.row?2:1}" data-iris-row="${i}" style="cursor:pointer"><title>Row ${i+1}: ${esc(lab.datasets.iris.rows[i][4])} · Cluster ${labels[i]}</title></circle>`).join('')}<text x="${W/2}" y="${H-6}" fill="#808b9a" font-size="9" text-anchor="middle">${short[state.x]} (standardized)</text><text x="12" y="${H/2}" transform="rotate(-90 12 ${H/2})" fill="#808b9a" font-size="9" text-anchor="middle">${short[state.y]} (standardized)</text></svg>`;
}
function clusteringView(interactive) {const opts=['Sepal length','Sepal width','Petal length','Petal width'];return `<div class="content-stack">${interactive?card('Explore the fitted clusters',`<div class="card-body"><div class="form-grid wide">${selectField('x','Horizontal axis',opts.map((v,i)=>[i,v]),state.x)}${selectField('y','Vertical axis',opts.map((v,i)=>[i,v]),state.y)}${numericField('row','Highlight Iris row',state.row+1,1,150,1)}</div><p class="section-note" style="margin-top:12px">Change the axes or select a point to inspect its cluster membership. Both models were fitted on all four features.</p></div>`,'Three clusters · training data standardized'):''}<div class="two-charts">${[['kmeans','K-Means','Silhouette 0.4599'],['em','EM · Gaussian mixture','Silhouette 0.3742']].map(([method,title,sub])=>card(title,`<div class="chart-frame" id="scatter-${method}">${scatter(method)}</div><div class="chart-legend">${colors.map((c,i)=>`<span><i class="chart-dot" style="background:${c}"></i>Cluster ${i}</span>`).join('')}</div>`,sub)).join('')}</div>${interactive?card('Selected record',`<div class="card-body" id="cluster-membership"></div>`,'Soft membership probabilities from the fitted Gaussian mixture'):note('K-Means has the larger silhouette in this run. EM agrees more closely with the known species (adjusted Rand index: 0.9039 vs 0.6201). Cluster IDs are arbitrary and are not species labels.')}</div>`;}
function updateClustering(){if($('#scatter-kmeans'))$('#scatter-kmeans').innerHTML=scatter('kmeans');if($('#scatter-em'))$('#scatter-em').innerHTML=scatter('em');const area=$('#cluster-membership');if(area){const model=lab.models.clustering;area.innerHTML=`<p class="insight"><b>Row ${state.row+1} · ${esc(lab.datasets.iris.rows[state.row][4])}</b> &nbsp; K-Means cluster ${model.kmeans[state.row]} · EM cluster ${model.em[state.row]}</p>${probabilities(['Cluster 0','Cluster 1','Cluster 2'],model.memberships[state.row])}`;}}
function bindVisuals(){if(state.id===5)updateClustering();}

document.addEventListener('click',event=>{
 const nav=event.target.closest('[data-exp]'); if(nav){route(Number(nav.dataset.exp),'learn');window.scrollTo({top:0,behavior:'smooth'});return;}
 const tab=event.target.closest('[data-tab]');if(tab){route(state.id,tab.dataset.tab);return;}
 const fold=event.target.closest('[data-fold]');if(fold){state.fold=Number(fold.dataset.fold);updateFold();return;}
 const point=event.target.closest('[data-iris-row]');if(point){state.row=Number(point.dataset.irisRow);const input=$('input[name="row"]');if(input)input.value=state.row+1;updateClustering();return;}
 const sample=event.target.closest('[data-sample]');if(sample){$('#message-input').value=sample.dataset.sample==='spam'?'Congratulations! Claim your free cash prize now':'Can we meet at the library after class?';$('#document-form').requestSubmit();return;}
 const action=event.target.closest('[data-action]')?.dataset.action;if(!action||!lab)return;const exp=lab.experiments[state.id-1];
 if(action==='copy-output')copy(exp.output);if(action==='copy-source')copy(exp.source);if(action==='download-output')downloadText(exp.output,exp.filename.replace('.py','_output.txt'));
 if(action==='page-prev'){state.page--;renderDatasetRows();}if(action==='page-next'){state.page++;renderDatasetRows();}
 if(action==='download-marks'){const data=new FormData($('#marks-form'));if(!$('#marks-form').reportValidity())return;downloadText('student,marks\n'+[0,1,2].map(i=>`${['A','B','C'][i]},${Number(data.get('mark'+i))}`).join('\n')+'\n','colab_demo.csv','text/csv');toast('CSV downloaded');}
});
document.addEventListener('change',event=>{const target=event.target;if(target.id==='mobile-experiment'){route(Number(target.value),'learn');return;}if(target.id==='dataset-select'){state.dataset=target.value;state.page=0;state.query='';renderPanel();return;}if(target.id==='gaussian-dataset'){state.gaussian=target.value;renderPanel();return;}if(state.id===5&&state.tab==='interactive'){if(target.name==='x')state.x=Number(target.value);if(target.name==='y')state.y=Number(target.value);if(target.name==='row'){state.row=Math.max(0,Math.min(149,(Number(target.value)||1)-1));target.value=state.row+1;}updateClustering();}});
document.addEventListener('input',event=>{if(state.id===5&&state.tab==='interactive'&&event.target.name==='row'){state.row=Math.max(0,Math.min(149,(Number(event.target.value)||1)-1));updateClustering();}if(event.target.id==='dataset-search'){state.query=event.target.value;state.page=0;renderDatasetRows();}});
document.addEventListener('keydown',event=>{if(event.target.getAttribute('role')==='tab'&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=['learn','pyq','output','interactive','dataset','program'];const index=tabs.indexOf(state.tab);const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:tabs.length-1))%tabs.length;route(state.id,tabs[next]);setTimeout(()=>$(`#tab-${tabs[next]}`)?.focus(),0);}});
$('#share-button').innerHTML=icon('share');$('#share-button').addEventListener('click',()=>copy(location.href));
window.addEventListener('hashchange',()=>{if(lab){readRoute();render();}});
try {const response=await fetch('assets/lab-data.json');if(!response.ok)throw new Error('The lab data could not be loaded.');lab=await response.json();readRoute();render();}
catch(error){$('#workspace').innerHTML=`<div class="loading-state"><h1>The workbench could not load</h1><p>${esc(error.message)}</p><button class="button primary" onclick="location.reload()">Try again</button></div>`;}
